import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate discountPercent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create an invoice from customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate format and validity
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime())) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty
  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Enrich and validate lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: line.discountPercent ?? 0,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total amount for a line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Add a line to an invoice. If the SKU already exists, increase its qty.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check if status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if line with this SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    newLines.push({
      sku: sku,
      name: product.name,
      qty: qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent ?? 0,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

